      traceInvoke("invokeSendPrompt", params);
      edgeLog(
        "INVOKE_SEND_PROMPT_ENTER",
        `argsLen=${args.length} arg0Keys=${args[0] && typeof args[0] === "object" ? Object.keys(args[0]).join(",") : "n/a"} arg1Keys=${args[1] && typeof args[1] === "object" ? Object.keys(args[1]).join(",") : "n/a"} paramsJson=${JSON.stringify(params)}`
      );
      if (!params || !Array.isArray(params.blocks) || params.blocks.length === 0) {
        edgeLog("INVOKE_SEND_PROMPT_FAIL_NO_BLOCKS", `argsLen=${args.length} extractedType=${typeof params}`);
        return fail(new Error(`invokeSendPrompt requires {blocks[]} \u2014 got argsLen=${args.length} extractedType=${typeof params} keys=${params && typeof params === "object" ? Object.keys(params).join(",") : "n/a"}`));
      }
      if (params.createParams?.__jsonParseError) {
        edgeLog("INVOKE_SEND_PROMPT_FAIL_JSON_PARSE", `err=${String(params.createParams.__jsonParseError)}`);
        return fail(new Error(`createParams JSON parse failed: ${String(params.createParams.__jsonParseError)}`));
      }
      try {
        let convId = params.conversationId;
        let newlyCreated = false;
        if (!convId) {
          const createParams = params.createParams && typeof params.createParams === "object" ? params.createParams : {};
          edgeLog(
            "INVOKE_SEND_PROMPT_CREATE",
            `createParamsKeys=${Object.keys(createParams).join(",") || "(none)"} createParamsJson=${JSON.stringify(createParams)}`
          );
          let created;
          try {
            created = await conv.create(createParams);
          } catch (createErr) {
            edgeLog(
              "INVOKE_SEND_PROMPT_CREATE_THROW",
              `name=${createErr?.name} msg=${createErr?.message} stack=${createErr?.stack?.split("\n").slice(0, 5).join(" | ")}`
            );
            return fail(new Error(`conv.create threw: ${createErr?.message ?? String(createErr)}`));
          }
          edgeLog(
            "INVOKE_SEND_PROMPT_CREATE_RESULT",
            `type=${typeof created} keys=${created && typeof created === "object" ? Object.keys(created).join(",") : "n/a"} json=${JSON.stringify(created)}`
          );
          if (!created || typeof created !== "object") {
            return fail(new Error(`conv.create returned non-object: ${JSON.stringify(created)}`));
          }
          if ("errorCode" in created) {
            return fail(new Error(`create session failed: ${created.errorCode}${created.message ? ` \u2014 ${created.message}` : ""}`));
          }
          if (!created.info || typeof created.info !== "object" || typeof created.info.id !== "string") {
            return fail(new Error(`conv.create returned {info} without valid .id: ${JSON.stringify(created)}`));
          }
          convId = created.info.id;
          newlyCreated = true;
          edgeLog("INVOKE_SEND_PROMPT_CREATE_OK", `newConvId=${convId}`);
        }
        const sendOptions = params.options && typeof params.options === "object" ? params.options : {};
        edgeLog(
          "INVOKE_SEND_PROMPT_SEND",
          `convId=${convId} blocks=${JSON.stringify(params.blocks)} options=${JSON.stringify(sendOptions)}`
        );
        let result;
        try {
          result = await conv.sendPrompt(convId, params.blocks, sendOptions);
        } catch (sendErr) {
          edgeLog(
            "INVOKE_SEND_PROMPT_SEND_THROW",
            `convId=${convId} name=${sendErr?.name} msg=${sendErr?.message} stack=${sendErr?.stack?.split("\n").slice(0, 8).join(" | ")}`
          );
          return fail(new Error(`conv.sendPrompt threw: ${sendErr?.message ?? String(sendErr)} (see edge-sync.log for full stack)`));
        }
        edgeLog(
          "INVOKE_SEND_PROMPT_SEND_OK",
          `convId=${convId} resultType=${typeof result} resultJson=${JSON.stringify(result)}`
        );
        return ok({
          result: result ?? null,
          newConversationId: newlyCreated ? convId : void 0,
          conversationId: convId
        });
      } catch (err) {
        edgeLog(
          "INVOKE_SEND_PROMPT_OUTER_CATCH",
          `name=${err?.name} msg=${err?.message} stack=${err?.stack?.split("\n").slice(0, 8).join(" | ")}`
        );
        return fail(err);
      }
